CREATE TABLE tag_map (
    tag_id TEXT PRIMARY KEY,
    machine_id TEXT,
    signal TEXT,
    unit TEXT,
    register TEXT,
    scale DOUBLE PRECISION
);

CREATE TABLE machines (
    id TEXT PRIMARY KEY,
    processing_time_s DOUBLE PRECISION,
    availability_pct DOUBLE PRECISION,
    mttr_s DOUBLE PRECISION,
    power_working_kw DOUBLE PRECISION,
    power_idle_kw DOUBLE PRECISION
);

CREATE TABLE buffers (
    id TEXT PRIMARY KEY,
    capacity INTEGER,
    before TEXT,
    after TEXT
);

CREATE TABLE raw_ingest (
    ingested_at TIMESTAMPTZ,
    source TEXT,
    payload JSONB
);

CREATE TABLE events (
    ts TIMESTAMPTZ,
    machine_id TEXT,
    reason_code TEXT,
    duration_s DOUBLE PRECISION,
    energy_kwh DOUBLE PRECISION
);

CREATE TABLE samples (
    ts TIMESTAMPTZ,
    machine_id TEXT,
    tag TEXT,
    value DOUBLE PRECISION
);

CREATE TABLE ingest_watermark (
    source TEXT PRIMARY KEY,
    max_event_ts TIMESTAMPTZ
);

-- Populate dimension tables with data from requirements
INSERT INTO machines (id, processing_time_s, availability_pct, mttr_s, power_working_kw, power_idle_kw) VALUES
('M1', 150, 98, 600, 4.0, 0.4),
('M2', 120, 97, 900, 5.0, 0.5),
('M3', 180, 95, 1200, 6.0, 0.6),
('M4', 120, 97, 900, 5.0, 0.5),
('M5', 150, 98, 600, 4.0, 0.4);

INSERT INTO buffers (id, capacity, before, after) VALUES
('B0', 20, 'source', 'M1'),
('B1', 8, 'M1', 'M2'),
('B2', 8, 'M2', 'M3'),
('B3', 8, 'M3', 'M4'),
('B4', 8, 'M4', 'M5');

-- Create views to expose typed fact tables over raw_ingest
CREATE VIEW events_view AS SELECT T1.ts, T1.machine_id, T1.reason_code, T1.duration_s, T1.energy_kwh FROM raw_ingest AS T1 INNER JOIN JSONB_EACH(T1.payload) AS T2 ON T1.source = T2.key WHERE T2.value::TEXT LIKE '%event%';

CREATE VIEW samples_view AS SELECT T1.ts, T1.machine_id, T1.tag, T1.value FROM raw_ingest AS T1 INNER JOIN JSONB_EACH(T1.payload) AS T2 ON T1.source = T2.key WHERE T2.value::TEXT LIKE '%sample%';
